from glb_io import read_glb,arrays
base=ROOT/'projects/fishing-2d/experiments/six-fish-database-20261104/carp';old=base/'width-r1';out=base/'width-r2';out.mkdir();cfg=ROOT/'resources/volume-fish/carp-sop-front-material-r5-20261031.json';c=json.loads(cfg.read_text());W,H=c['source_size'];up=np.array(c['upper_inner_edge_px']);down=np.array(c['lower_inner_edge_px']);profile=json.loads((ROOT/'resources/volume-fish/carp-sop-final-20261031.profile.json').read_text());line=np.array(profile['oral_jaws']['slit_path'])*[W,H];half=profile['oral_jaws']['gap']*W/2
